mapper.select:
SELECT /* LGUTLC00080.retrieveDynamicQueryPopList */ query_id , query_name , description AS query_desc , access_level , access_group FROM XXLGE_QUERY WHERE access_group = #{accessGroup}
AND UPPER(query_name) LIKE UPPER(#{keyword}) || '%'
ORDER BY access_group, query_name

mapper.insert:
INSERT INTO /* LGUTLC00080.insertDynamicQueryExecHistory */
            XXLGE_QUERY_EXEC_INSTR_RSLT_N (
    application_user_id,upload_session_id,query_id,org_id,sql_content,parent_program_id,sql_text, concurrent_request_id,
    sql_execution_result_row_count,sql_error_content,created_by,creation_date,last_updated_by,last_update_date,last_update_login
) VALUES (
    #{applicationUserId},#{sessionId},#{queryId},#{defaultOrgId},#{generatedQuery,jdbcType=CLOB},#{programId},#{sqlText}, #{batchRequestId},
    #{resultCount},#{statusCode},#{applicationUserId},SYSDATE,#{applicationUserId},SYSDATE,#{applicationUserId}
)

mapper.update:
UPDATE /* LGUTLC00080.updateDynamicQueryExecHistory */
       XXLGE_QUERY_EXEC_INSTR_RSLT_N
   SET sql_execution_result_row_count = #{sqlExecutionResultRowCount}
     , batch_job_start_date           = DECODE(#{batchJobStartDate},'SYSDATE',SYSDATE)
     , batch_job_end_date             = DECODE(#{batchJobEndDate},'SYSDATE',SYSDATE)
     , sql_error_content               = #{rsltStatusCode}
     , result_content                 = #{resultContent}
     , last_updated_by                = #{userId}
     , last_update_date               = SYSDATE
     , last_update_login              = #{userId}
 WHERE application_user_id            = #{applicationUserId}
   AND upload_session_id              = #{sessionId}
   AND query_id                       = #{queryId}
   AND org_id                         = #{defaultOrgId}

