mapper.insert:
INSERT INTO /* LGUTLC00080.insertDynamicQueryUseLog */
            XXLGE_DQ_USE_T (
    organization_id,user_id,form_id,query_id,access_group,query_name,
    end_date,creation_date,created_by,last_update_date,last_updated_by,last_update_login
) VALUES (
    #{defaultOrgId},#{applicationUserId},#{formId},#{queryId},(SELECT access_group FROM XXLGE_QUERY WHERE query_id = #{queryId}),(SELECT query_name FROM XXLGE_QUERY WHERE query_id = #{queryId}),
    SYSDATE,SYSDATE,#{applicationUserId},SYSDATE,#{applicationUserId},#{applicationUserId}
)
